formula_sources.getWheelNodeCost:
function getWheelNodeCost(ring, currentLvl, mult = 1.0) {
                    const c = WHEEL_COST_CURVE[ring] || WHEEL_COST_CURVE[1];
                    const raw = c.base * Math.pow(c.growth, Math.max(0, currentLvl)) * Math.max(0.1, mult);
                    return Math.round(raw / 100000) * 100000;
                }

formula_sources.getWheelBonuses:
function getWheelBonuses() {
                    const bonuses = {
                        weapon_dmg_pct: 0, spell_dmg_pct: 0, spell_cd_pct: 0,
                        max_hp_pct: 0, max_mana_pct: 0, all_resist_pct: 0,
                        physical_reduction_pct: 0, crit_chance_pct: 0, crit_damage_pct: 0,
                        life_leech_pct: 0, mana_leech_pct: 0,
                        fatal_impeto_pct: 0, fatal_eco_pct: 0,
                        fatal_baluarte_pct: 0, fatal_execucao_pct: 0,
                        spell_damage_bonus: {}, maestria_gem_spell: null,
                    };
                    if ((playerState.level || 0) < WHEEL_MIN_LEVEL) return bonuses;

                    for (const key in WHEEL_NODE_DEFS) {
                        const lvl = getWheelNodeLevel(key);
                        if (lvl <= 0) continue;
                        const def = WHEEL_NODE_DEFS[key];
                        const mult = getWheelVocationMultiplier(def.path);
                        for (const effectKey in def.effects) {
                            if (bonuses[effectKey] === undefined) continue;
                            bonuses[effectKey] += def.effects[effectKey] * lvl * mult;
                        }
                    }

                    // Teto do Knight/Elite Knight no bônus de arma da Furia — espelho do mesmo
                    // teto em idleWheelBonuses() (PHP). Só sobre weapon_dmg_pct, não afeta os
                    // outros efeitos da Furia nem o caminho de outra vocação.
                    if (isKnightVocation() && bonuses.weapon_dmg_pct > KNIGHT_FURIA_WEAPON_DMG_CAP_PCT) {
                        bonuses.weapon_dmg_pct = KNIGHT_FURIA_WEAPON_DMG_CAP_PCT;
                    }

                    // ── MAESTRIA: bônus de dano por magia (espelho de idleWheelBonuses). ──
                    const map = getMaestriaSpellMap();
                    const addSpellBonus = (spell, pct) => {
                        if (!spell || pct <= 0) return;
                        bonuses.spell_damage_bonus[spell] = (bonuses.spell_damage_bonus[spell] || 0) + pct;
                    };
                    const m1Lvl = getWheelNodeLevel('maestria_1');
                    if (m1Lvl > 0) addSpellBonus(map['1'], 2.0 * m1Lvl);

                    const m2Lvl = getWheelNodeLevel('maestria_2');
                    if (m2Lvl > 0) addSpellBonus(map['2'], 2.5 * m2Lvl);

                    const gemLvl = getWheelNodeLevel('maestria_gem');
                    if (gemLvl > 0) addSpellBonus(map['3'], 3.0 * gemLvl);

                    for (const k in bonuses) {
                        if (typeof bonuses[k] === 'number') bonuses[k] = Math.round(bonuses[k] * 100) / 100;
                    }
                    for (const sk in bonuses.spell_damage_bonus) {
                        bonuses.spell_damage_bonus[sk] = Math.round(bonuses.spell_damage_bonus[sk] * 100) / 100;
                    }
                    return bonuses;
                }

formula_sources.getWaveDistribution:
function getWaveDistribution(lvl) {
                    lvl = Math.max(0, Math.min(40, parseInt(lvl, 10) || 0));
                    if (lvl <= 20) {
                        const four = lvl >= 5 ? Math.min(25, (lvl - 4) * 1.5625) : 0;
                        const three = 5 + lvl * 1.25;
                        const two = 25 + lvl * 1.0;
                        const one = Math.max(0, 100 - two - three - four);
                        return [one, two, three, four, 0, 0, 0, 0];
                    }
                    const e = lvl - 20;
                    const three = 30 - e * 1.0;
                    const four = 25 - e * 0.5;
                    const five = e * 1.0;
                    const six = Math.max(0, e - 4) * 1.25;
                    const seven = Math.max(0, e - 8) * 1.25;
                    const eight = Math.max(0, e - 12) * 1.875;
                    const two = Math.max(0, 100 - three - four - five - six - seven - eight);
                    return [0, two, three, four, five, six, seven, eight];
                }

formula_sources.getWaveExpectedSize:
function getWaveExpectedSize(lvl) {
                    return getWaveDistribution(lvl).reduce((sum, chance, index) => sum + (index + 1) * chance / 100, 0);
                }

formula_sources.getWaveUnlockLevels:
function getWaveUnlockLevels() {
                    const unlock = {};
                    for (let l = 0; l <= 40; l++) {
                        const d = getWaveDistribution(l);
                        for (let i = 0; i < d.length; i++) {
                            if (d[i] > 0 && unlock[i + 1] === undefined) unlock[i + 1] = l;
                        }
                    }
                    return unlock;
                }

formula_sources.getPotionMasteryPercent:
function getPotionMasteryPercent(lvl) {
                    const l = Math.max(0, Math.min(50, parseInt(lvl, 10) || 0));
                    return l * 2;
                }

formula_sources.rollCriticalHit:
function rollCriticalHit(critLvl, gearChancePct = 0, gearDmgPct = 0) {
                    const lvl = Math.max(0, critLvl || 0);
                    // Rebalanceamento 2026-07: chance sobe suave até 20% no nível 20 (era travado
                    // em 25% desde o nível 5). Dano extra sobe suave até +100% no nível 20 (era até
                    // +150%) — crítico máximo agora causa 200% do dano normal, não 250%.
                    const baseChance = lvl > 0 ? getAttrPercent(lvl, 10, 20) : 0;
                    const chance = Math.min(100, baseChance + (gearChancePct || 0)) / 100;
                    if (chance <= 0) {
                        return { isCrit: false, multiplier: 1.0 };
                    }
                    if (Math.random() < chance) {
                        const baseExtraRatio = lvl > 0 ? getAttrPercent(lvl, 50, 100) / 100 : 0;
                        const extraRatio = baseExtraRatio + (gearDmgPct || 0) / 100;
                        return { isCrit: true, multiplier: 1.0 + extraRatio };
                    }
                    return { isCrit: false, multiplier: 1.0 };
                }

formula_sources.getCritExtraDamage:
function getCritExtraDamage(lvl) {
                    if (lvl <= 0) return 0;
                    return getAttrPercent(lvl, 50, 100);
                }

formula_sources.getDodgePercent:
function getDodgePercent(lvl) {
                    return getAttrPercent(Math.max(0, Math.min(20, lvl || 0)), 6, DODGE_ATTR_CAP);
                }

formula_sources.renderLeechPanel:
function renderLeechPanel() {
                    const lvl = playerState.leechLvl || 0;
                    renderAttrCard('leech', lvl, (l) => [
                        { label: 'Absorção de Vida', value: getAttrPercent(l, 12.5, 25).toFixed(1).replace(/\.0$/, '') + '%' }
                    ]);
                }

